onCurrencyInput(evt: Event) {
const value = (evt.target as HTMLInputElement).value;
const num = parseInt(value.replace(/[$,]/g, ‘’), 10);

// [demidn] A bit workaround way for preventing users from typing letters.
// We can not just always set this.amount = isNaN(num) ? 0 : num, because first time amount will be changed to 0
// and change detection will work, howevever if user continue typing letters, we are changing amount from 0 to 0
// same value and change detection will not run. So here we first set it to null and detect changes and then set to real
// value and mark for check - in this case change detection will work always.
this.amount = null;
this.changeDetectorRef.detectChanges();
this.amount = isNaN(num) ? 0 : num;
this.changeDetectorRef.markForCheck();
}

